"""Reading and writing ``data/medicines.yaml``.

The committed file is the reproducible corpus definition: resolved URLs, per-language
revision dates and a SHA-256 per downloaded file (SPEC sections 5 and 8).
"""

from __future__ import annotations

from pathlib import Path

import yaml

from medleaf.models import DocumentRef, Lang, Medicine

HEADER = """\
# MedLeaf corpus definition.
#
# Source: European Medicines Agency (EMA) EPAR product information. Reproduced with EMA
# acknowledged as the source, in line with EMA's legal notice (checked 2026-10-15).
#
# Generated by `medleaf resolve`. URLs are resolved from EMA's nightly bulk export
# (medicines-output-medicines-report_en.xlsx) and each medicine's EPAR page; none are
# guessed. The SHA-256 values pin the corpus version: a mismatch on `medleaf download`
# means EMA republished the document, not that the download failed.
"""


def load_medicines(path: Path) -> list[Medicine]:
    """Load the corpus definition. Missing file yields an empty corpus, not an error."""
    if not path.exists():
        return []
    data = yaml.safe_load(path.read_text(encoding="utf-8")) or {}
    records = data.get("medicines", [])
    return [Medicine.model_validate(record) for record in records]


def dump_medicines(path: Path, medicines: list[Medicine]) -> None:
    """Write the corpus definition, preserving the header comment block."""
    payload = {
        "medicines": [
            medicine.model_dump(mode="json", exclude_none=False) for medicine in medicines
        ]
    }
    body = yaml.safe_dump(payload, allow_unicode=True, sort_keys=False, width=100)
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(HEADER + body, encoding="utf-8")


def upsert_medicine(medicines: list[Medicine], medicine: Medicine) -> list[Medicine]:
    """Replace a medicine by slug, or append it, keeping the list order stable."""
    for index, existing in enumerate(medicines):
        if existing.slug == medicine.slug:
            medicines[index] = medicine
            return medicines
    medicines.append(medicine)
    return medicines


def slugify(name: str) -> str:
    """Turn an EMA brand name into a stable file-friendly slug."""
    cleaned = name.lower()
    for char in (" ", "/", "(", ")", ",", ".", "'", "\u2019"):
        cleaned = cleaned.replace(char, "-")
    while "--" in cleaned:
        cleaned = cleaned.replace("--", "-")
    return cleaned.strip("-")


__all__ = [
    "DocumentRef",
    "Lang",
    "Medicine",
    "dump_medicines",
    "load_medicines",
    "slugify",
    "upsert_medicine",
]
